script.setup:
const fs = `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 outColor;
uniform float u_time;
uniform vec2 u_resolution;
uniform float u_speed;
uniform float u_height;
uniform float u_chop;
uniform vec3 u_water;
uniform vec4 u_mouse;

float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
float noise(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f); return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y); }
float waves(vec2 p){
 float t=u_time*u_speed;
 float h=0.0;
 h+=sin(dot(p,vec2(0.82,0.57))*0.72-t*1.05)*0.52;
 h+=sin(dot(p,vec2(-0.37,0.93))*1.17-t*1.38)*0.26;
 h+=sin(dot(p,vec2(0.98,-0.2))*2.07-t*1.86)*0.12;
 float a=0.08; float f=3.4;
 for(int i=0;i<4;i++){
  vec2 q=p*f+vec2(t*0.6,-t*0.45);
  h+=(noise(q)-0.5)*a*u_chop;
  p=mat2(0.8,-0.6,0.6,0.8)*p; f*=1.93; a*=0.48;
 }
 return h*u_height;
}
vec3 sky(vec3 rd){
 vec3 low=vec3(0.65,0.79,0.90), high=vec3(0.12,0.34,0.60);
 vec3 c=mix(low,high,pow(max(rd.y,0.0),0.55));
 vec3 sun=normalize(vec3(-0.50,0.25,-0.83));
 float s=max(dot(rd,sun),0.0);
 c+=vec3(1.0,0.81,0.56)*(pow(s,90.0)*0.38+pow(s,1000.0)*3.0);
 float cloud=noise(rd.xz*4.0/(max(rd.y,0.08))+vec2(0.025*u_time));
 c=mix(c,vec3(0.88,0.91,0.91),smoothstep(0.58,0.85,cloud)*smoothstep(0.01,0.25,rd.y)*0.3);
 return c;
}
void main(){
 vec2 uv=(2.0*gl_FragCoord.xy-u_resolution)/u_resolution.y;
 float mx=u_mouse.x/u_resolution.x-0.5;
 vec3 ro=vec3(0.0,3.6,7.0);
 vec3 target=vec3(mx*1.8,0.1,-5.0);
 vec3 fw=normalize(target-ro), rt=normalize(cross(fw,vec3(0,1,0))), up=cross(rt,fw);
 vec3 rd=normalize(fw*1.7+rt*uv.x+up*uv.y);
 vec3 col=sky(rd);
 if(rd.y<0.0){
  float lo=0.0, hi=min((ro.y+u_height*1.5)/(-rd.y),230.0);
  for(int i=0;i<30;i++){
   float mid=(lo+hi)*0.5; vec3 p=ro+rd*mid;
   if(p.y>waves(p.xz)) lo=mid; else hi=mid;
  }
  float d=(lo+hi)*0.5; vec3 p=ro+rd*d;
  float eps=0.035+0.0003*d;
  float h=waves(p.xz);
  vec3 n=normalize(vec3(waves(p.xz-vec2(eps,0))-waves(p.xz+vec2(eps,0)),2.0*eps,waves(p.xz-vec2(0,eps))-waves(p.xz+vec2(0,eps))));
  vec3 r=reflect(rd,n);
  float fres=0.035+0.965*pow(1.0-max(dot(n,-rd),0.0),5.0);
  vec3 sun=normalize(vec3(-0.50,0.25,-0.83));
  float spec=pow(max(dot(r,sun),0.0),220.0);
  vec3 sea=u_water*(0.58+0.4*max(dot(n,sun),0.0));
  sea+=vec3(0.02,0.12,0.10)*smoothstep(-0.3,0.85,h/u_height);
  col=mix(sea,sky(r),fres*0.85)+vec3(1.0,0.85,0.64)*spec*1.8;
  float crest=smoothstep(0.62,0.84,h/u_height);
  float foam=crest*smoothstep(0.47,0.76,noise(p.xz*6.0+u_time*u_speed*0.25));
  foam*=u_chop*0.3;
  col=mix(col,vec3(0.72,0.85,0.82),clamp(foam,0.0,0.6));
  float haze=1.0-exp(-d*0.014);
  haze=max(haze,1.0-smoothstep(0.0,0.045,-rd.y));
  col=mix(col,sky(vec3(rd.x,0.0,rd.z)),haze);
 }
 col=col/(col+vec3(0.55));
 col=pow(col,vec3(0.92));
 float vignette=1.0-0.13*dot(v_uv-0.5,v_uv-0.5);
 outColor=vec4(col*vignette,1.0);
}`;
ctx.state.program=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs);
